 "Is there a refund policy?": "Czy jest polityka zwrotów?",
 "It could not be published. Try again.": "Nie udało się opublikować. Spróbuj ponownie.",
 "It disappears for everyone. Orders and payments are kept. Not possible while members still pay for it.": "Znika dla wszystkich. Zamówienia i płatności zostają. Niemożliwe, dopóki członkowie za nią płacą.",
 "It goes back to their card in 5 to 10 business days, and your share comes back from your Stripe balance. They get an email.": "Pieniądze wrócą na kartę w 5–10 dni roboczych, a Twoja część zostanie pobrana z salda Stripe. Kupujący dostanie e-mail.",
 "It goes live at": "Zostanie opublikowana pod adresem",
 "It has not been saved yet, so it will not be kept.": "Nie został jeszcze zapisany, więc nie zostanie zachowany.",
 "It has not been saved yet, so nothing you added will be kept.": "Nie został jeszcze zapisany, więc nic z dodanych rzeczy nie zostanie zachowane.",
 "It has to end after it starts.": "Musi kończyć się po rozpoczęciu.",
 "It hides before it shows, so it would never be on the page.": "Ukrywa się przed pokazaniem, więc nigdy nie byłoby go na stronie.",
 "It is a draft. Only you can see it until you publish.": "To wersja robocza. Do publikacji widzisz ją tylko Ty.",
 "It is gone for good, with its photos. To take it off your store and keep it, hide it instead.": "Zniknie na zawsze razem ze zdjęciami. Aby zdjąć ją ze sklepu i zachować, ukryj ją.",
 "It is hidden from your product page and its rating now. Storelib reads it and either brings it back or keeps it hidden.": "Jest już ukryta na stronie produktu i w ocenie. Storelib ją przeczyta i przywróci albo pozostawi ukrytą.",
 "It is not a Storelib product and is not listed anywhere else.": "To nie jest produkt Storelib i nie ma go nigdzie indziej.",
 "It is not connected yet, so nothing stops working.": "Nie jest jeszcze połączona, więc nic nie przestanie działać.",
 "It is off until you turn it on.": "Jest wyłączona, dopóki jej nie włączysz.",
 "It is removed from Messages. The email you got about it stays in your inbox, and the sender stays in your contacts.": "Zostanie usunięta z Wiadomości. E-mail, który o niej dostałeś, zostaje w skrzynce, a nadawca w kontaktach.",
 "It is removed with its numbers. Anything already sent stays in people's inboxes.": "Zostanie usunięta razem ze statystykami. To, co już wysłano, zostaje w skrzynkach.",
 "It is yours": "Jest Twój",
 "It opens soon": "Wkrótce się otworzy",
 "It plays on your page in the YouTube or Vimeo player.": "Odtwarza się na Twojej stronie w odtwarzaczu YouTube lub Vimeo.",
 "It replaces “{name}” at": "Zastąpi „{name}” pod adresem",
 "It shows as cancelled to members, and anyone going hears about it. You can put it back on.": "Członkowie zobaczą je jako odwołane, a uczestnicy dostaną wiadomość. Możesz je przywrócić.",
 "It starts as a draft. Add its lessons, then publish it.": "Zaczyna jako wersja robocza. Dodaj lekcje, a potem opublikuj.",
 "It stops at once for everyone partway through, and its history goes with it.": "Zatrzyma się od razu dla wszystkich w trakcie, a jej historia zniknie razem z nią.",
 "It usually arrives in 1 to 3 business days.": "Zwykle dociera w 1–3 dni robocze.",
