 "On order emails, so a buyer or a courier can reach you. It also helps your payment provider tell a real shop from a fraudulent one.": "W e-mailach o zamówieniach, aby kupujący lub kurier mógł się skontaktować. Pomaga też operatorowi płatności odróżnić prawdziwy sklep od oszustwa.",
 "On receipts, order emails and checkout.": "Na paragonach, w e-mailach o zamówieniach i w kasie.",
 "On receipts, order pages and every email your buyers get.": "Na paragonach, stronach zamówień i we wszystkich e-mailach do kupujących.",
 "On sale": "W sprzedaży",
 "On the About page and in Membership, beside the contact form.": "Na stronie O nas i w Członkostwie, obok formularza kontaktowego.",
 "On the home page": "Na stronie głównej",
 "On the way": "W drodze",
 "On the way to your bank": "W drodze do banku",
 "On their first visit, once the language is published. After that, what they pick.": "Przy pierwszej wizycie, gdy język jest opublikowany. Potem ten, który wybiorą.",
 "On your website": "Na Twojej stronie",
 "On {title}": "Do: {title}",
 "On. New people start it from now.": "Włączona. Nowe osoby zaczynają od teraz.",
 "Once it has passed, say": "Po upływie pokaż",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Gdy środki są dostępne, możesz je wypłacić; zwykle docierają do banku w 1–3 dni robocze.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Po rozpoczęciu nie da się tego cofnąć. Możesz zatrzymać te jeszcze niewysłane.",
 "Once per person": "Raz na osobę",
 "Once saved, they'll appear on your OnePage.": "Po zapisaniu pojawią się na OnePage.",
 "One a line, for example\nfree followers\ncrypto signal*": "Po jednym w linii, na przykład\ndarmowi obserwujący\nsygnał krypto*",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Jeden e-mail godzinę później z linkiem do wybranych rzeczy, tylko do osób z zaznaczonym newsletterem. Przestaje, gdy kupią.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Jeden e-mail godzinę później, tylko do osób z zaznaczonym newsletterem. Gdy pole jest ukryte, nikt go nie zaznaczy, więc przypomnienie nie wyjdzie.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Jedno wydarzenie ma cenę i nikt nie kupi biletu, dopóki nie połączysz wypłat.",
 "One event has a ticket price, but payouts are not connected, so nobody can buy it.": "Jedno wydarzenie ma cenę biletu, ale wypłaty nie są połączone, więc nikt go nie kupi.",
 "One every {value}": "Raz na {value}",
 "One field": "Jedno pole",
 "One field, or first and last name apart.": "Jedno pole albo imię i nazwisko osobno.",
 "One image at a time": "Jeden obraz naraz",
 "One line on cards and in Explore": "Jedna linijka na kartach i w Odkrywaj",
 "One more photo": "Jeszcze jedno zdjęcie",
 "One more thing, suggested before they pay": "Coś jeszcze, proponowane przed płatnością",
 "One price for every buyer.": "Jedna cena dla wszystkich kupujących.",
 "One reminder": "Jedno przypomnienie",
 "One time": "Jednorazowo",
 "One time price": "Cena jednorazowa",
 "One time purchase": "Zakup jednorazowy",
 "Online": "Online",
 "Only Storelib sees this.": "Widzi to tylko Storelib.",
 "Only YouTube and Vimeo links can be added as a video.": "Jako wideo można dodać tylko linki YouTube i Vimeo.",
 "Only buyers who asked for your news": "Tylko kupujący, którzy chcą dostawać wiadomości",
 "Only for me": "Tylko dla mnie",
 "Only if {phrase}": "Tylko jeśli {phrase}",
 "Only members ever see Learn. This decides which of them can open the lessons.": "Naukę widzą tylko członkowie. To decyduje, którzy z nich otworzą lekcje.",
 "Only on orders over an amount": "Tylko przy zamówieniach powyżej kwoty",
 "Only orders placed after you turn the app on are asked. Buyers who turned review emails off, or already reviewed, are never asked.": "Prośby dotyczą tylko zamówień złożonych po włączeniu aplikacji. Kupujący, którzy wyłączyli te e-maile lub już wystawili opinię, nie dostaną prośby.",
 "Only people who asked for your news get it.": "Dostają ją tylko osoby, które poprosiły o wiadomości.",
 "Only people who trigger it after you turn it on are sent anything. Someone who unsubscribes is never sent another email, wherever they are in the flow.": "Coś dostaną tylko osoby, które uruchomią ją po włączeniu. Kto się wypisze, nie dostanie już żadnego e-maila, niezależnie od etapu.",
 "Only people you invite": "Tylko zaproszone osoby",
 "Only photos and MP4, WebM or MOV videos.": "Tylko zdjęcia oraz filmy MP4, WebM lub MOV.",
 "Only these products": "Tylko te produkty",
 "Only to buyers who have not reviewed yet.": "Tylko do kupujących, którzy jeszcze nie wystawili opinii.",
 "Only to people who asked for your news": "Tylko do osób, które chcą dostawać wiadomości",
 "Only what Stripe needs to verify you in your country. It goes straight to Stripe and Storelib never keeps it.": "Tylko to, czego Stripe potrzebuje do weryfikacji w Twoim kraju. Trafia prosto do Stripe, Storelib tego nie przechowuje.",
 "Only you and your team can see it.": "Widzisz ją tylko Ty i zespół.",
 "Only you and your team see it until you publish. The Overview lists what to do first.": "Do publikacji widzisz ją tylko Ty i zespół. Przegląd pokazuje, od czego zacząć.",
