 "The daily figures start after the first nightly count. Today’s numbers below are live.": "Dane dzienne pojawią się po pierwszym nocnym liczeniu. Dzisiejsze liczby poniżej są na żywo.",
 "The default tier": "Poziom domyślny",
 "The details on your payments account.": "Dane Twojego konta płatności.",
 "The device and browser of the first page of each visit.": "Urządzenie i przeglądarka pierwszej strony każdej wizyty.",
 "The draft is removed and nothing is sent.": "Szkic zostanie usunięty i nic nie zostanie wysłane.",
 "The email": "E-mail",
 "The email and its numbers are removed from Storelib. What was sent stays in people's inboxes.": "E-mail i jego statystyki zostaną usunięte ze Storelib. To, co wysłano, zostaje w skrzynkach odbiorców.",
 "The email as your subscribers will get it, with your name filled in, to": "E-mail tak, jak dostaną go subskrybenci, z wpisanym Twoim imieniem, na",
 "The email could not be sent just now. Share this link with {email} yourself.": "Nie udało się teraz wysłać e-maila. Udostępnij ten link osobie {email} samodzielnie.",
 "The email was not changed. Try again.": "E-mail nie został zmieniony. Spróbuj ponownie.",
 "The email was not deleted. Try again.": "E-mail nie został usunięty. Spróbuj ponownie.",
 "The email you sign in with. Use another one if buyers should write somewhere else.": "E-mail, którym się logujesz. Użyj innego, jeśli kupujący mają pisać gdzie indziej.",
 "The emails your buyers get from your store: receipts, order and shipping updates, returns and the checkout reminder.": "E-maile, które kupujący dostają z Twojego sklepu: potwierdzenia, aktualizacje zamówień i wysyłki, zwroty oraz przypomnienie o płatności.",
 "The end has to be after the start.": "Koniec musi być po początku.",
 "The event could not be saved.": "Nie udało się zapisać wydarzenia.",
 "The export could not be made. Try again.": "Nie udało się wyeksportować. Spróbuj ponownie.",
