 "The file did not import.": "Plik nie został zaimportowany.",
 "The files could not be downloaded.": "Nie udało się pobrać plików.",
 "The first name of the person running the business, as on their ID.": "Imię osoby prowadzącej firmę, jak w dokumencie.",
 "The first payout setup banner no longer shows after a successful payout has been completed.": "Baner konfiguracji pierwszej wypłaty nie pojawia się już po zrealizowanej wypłacie.",
 "The first words of the email show here unless you add preview text.": "Tu pojawią się pierwsze słowa e-maila, chyba że dodasz tekst podglądu.",
 "The flow ends for them.": "Przepływ się dla nich kończy.",
 "The gallery arrives with the next Storelib database update. Once it has run, add pictures and videos here.": "Galeria pojawi się z następną aktualizacją bazy danych Storelib. Potem dodasz tu obrazy i wideo.",
 "The gallery is a list.": "Galeria to lista.",
 "The gallery is full ({galleryMax}). Remove one first.": "Galeria jest pełna ({galleryMax}). Najpierw coś usuń.",
 "The image did not upload. Try again.": "Obraz nie został przesłany. Spróbuj ponownie.",
 "The invite could not be made. Try again.": "Nie udało się utworzyć zaproszenia. Spróbuj ponownie.",
 "The invites did not go out.": "Zaproszenia nie zostały wysłane.",
 "The invoice could not be made. Try again.": "Nie udało się utworzyć faktury. Spróbuj ponownie.",
 "The items, totals, tracking and links stay as they are, filled in from each order.": "Pozycje, sumy, śledzenie i linki zostają bez zmian, uzupełniane z każdego zamówienia.",
 "The language of your dashboard": "Język panelu",
 "The languages your website is offered in. Visitors pick theirs from the language selector, and each language has its own address, like /fr.": "Języki, w których dostępna jest Twoja strona. Odwiedzający wybierają swój w przełączniku, a każdy język ma własny adres, np. /fr.",
 "The lessons show up here as soon as they are added.": "Lekcje pojawią się tu zaraz po dodaniu.",
 "The line shown after the subject in the inbox": "Linijka widoczna po temacie w skrzynce odbiorczej",
 "The link could not be copied.": "Nie udało się skopiować linku.",
 "The links and buttons on your OnePage that were tapped most, by the name they have on the page, and how many people tapped each.": "Linki i przyciski na Twojej OnePage klikane najczęściej, z nazwą ze strony i liczbą osób, które je kliknęły.",
 "The links that brought the most people in during the last {days} days.": "Linki, które przyciągnęły najwięcej osób w ostatnich {days} dniach.",
 "The list could not be loaded.": "Nie udało się wczytać listy.",
 "The log could not be loaded.": "Nie udało się wczytać dziennika.",
 "The members could not be loaded.": "Nie udało się wczytać członków.",
 "The membership could not be saved.": "Nie udało się zapisać członkostwa.",
 "The money goes back to the buyer's original payment method, and they get an email about it.": "Pieniądze wrócą na pierwotną metodę płatności kupującego, a on dostanie o tym e-mail.",
 "The money is back in your available balance. Check your bank details, then cash out again.": "Pieniądze wróciły na dostępne saldo. Sprawdź dane bankowe i wypłać ponownie.",
 "The most one buyer can take in one order": "Najwięcej, ile kupujący może wziąć w jednym zamówieniu",
 "The new account is used for your next payout.": "Nowe konto zostanie użyte przy następnej wypłacie.",
 "The newest exchange rates are from {asOf}, which is too old to use. Markets show your own prices until new rates arrive.": "Najnowsze kursy są z {asOf}, zbyt stare, by ich użyć. Rynki pokazują Twoje ceny, dopóki nie przyjdą nowe kursy.",
 "The number sold, on the product page": "Liczba sprzedanych na stronie produktu",
 "The order did not save.": "Nie zapisano kolejności.",
 "The order moves to the new address, and the receipt with the download link is sent there now.": "Zamówienie przejdzie na nowy adres, a potwierdzenie z linkiem do pobrania zostanie tam teraz wysłane.",
 "The order moves to the new address. Nothing is sent, as nothing in it has been paid for yet.": "Zamówienie przejdzie na nowy adres. Nic nie zostanie wysłane, bo nic jeszcze nie zapłacono.",
 "The order was not saved.": "Nie zapisano kolejności.",
 "The other side of the card. A passport has no back.": "Druga strona karty. Paszport nie ma tyłu.",
 "The owner and admins write the rules.": "Zasady piszą właściciel i administratorzy.",
 "The pages opened most, with how many people opened each. A page opened again within half an hour counts once.": "Najczęściej otwierane strony i liczba osób, które je otworzyły. Strona otwarta ponownie w ciągu pół godziny liczy się raz.",
