 "There are no rules yet. Write them in Rules and policies.": "Brak zasad. Napisz je w Zasadach i regulaminach.",
 "There are no subscribers to export": "Brak subskrybentów do eksportu",
 "There is no payment on that ticket to give back.": "Ten bilet nie ma płatności do zwrotu.",
 "There is no space to post in. Add one under Spaces.": "Brak przestrzeni do publikowania. Dodaj ją w Przestrzeniach.",
 "There is nothing available to cash out yet.": "Nie ma jeszcze nic do wypłaty.",
 "There were no paying members at the start of this period, so there is no rate yet.": "Na początku okresu nie było płacących członków, więc wskaźnika jeszcze nie ma.",
 "These will appear on your OnePage": "Pojawią się na Twojej OnePage",
 "They are off for now. You can turn them on in": "Na razie są wyłączone. Możesz je włączyć w",
 "They are removed from your files, and anything that still shows one of them will show nothing.": "Zostaną usunięte z plików, a miejsca, które je pokazują, będą puste.",
 "They are unsubscribed and get no more of your emails.": "Zostanie wypisany i nie dostanie już Twoich e-maili.",
 "They can ask again later.": "Może poprosić ponownie później.",
 "They can open the community and post again, and keep their points, level and posts.{free}": "Może znów otworzyć społeczność i publikować, zachowując punkty, poziom i posty.{free}",
 "They can read everything but cannot post, comment, react or chat until it ends.": "Może wszystko czytać, ale do końca nie może publikować, komentować, reagować ani czatować.",
 "They can't place an order until they click the link we email them when they sign up. Turns on sign in as well.": "Nie złożą zamówienia, dopóki nie klikną linku z e-maila wysłanego przy rejestracji. Włącza też logowanie.",
 "They get access again now, and keep their points, level and posts.{free}": "Odzyskuje dostęp teraz i zachowuje punkty, poziom i posty.{free}",
 "They get in without paying, and they are told what the ticket would have cost.": "Wchodzą bez płacenia i dowiadują się, ile kosztowałby bilet.",
 "They get this tier without paying, until you end it.": "Dostaje ten poziom bez płacenia, dopóki tego nie zakończysz.",
 "They have {points} now. ": "Ma teraz {points}.",
 "They lose access and cannot join again unless you unban them.": "Traci dostęp i nie może dołączyć ponownie, chyba że go odbanujesz.",
 "They lose access now and can join again. A paid membership keeps billing until they cancel it.": "Traci dostęp teraz i może dołączyć ponownie. Płatne członkostwo jest naliczane do czasu anulowania.",
 "They lose access until you bring them back. Their posts stay.": "Traci dostęp, dopóki go nie przywrócisz. Posty zostają.",
 "Things you ship: clothing, prints, merch, gear, with stock.": "Rzeczy, które wysyłasz: odzież, druki, gadżety, sprzęt, ze stanem magazynu.",
 "This": "To",
 "This action cannot be undone": "Tej operacji nie można cofnąć",
 "This browser cannot show notifications.": "Ta przeglądarka nie obsługuje powiadomień.",
 "This community is archived. Bring it back to change it.": "Ta społeczność jest zarchiwizowana. Przywróć ją, aby ją zmienić.",
 "This community is archived. Members can read it, nobody can post. Bring it back from Settings.": "Ta społeczność jest zarchiwizowana. Członkowie mogą czytać, nikt nie może publikować. Przywróć ją w Ustawieniach.",
 "This course's modules and lessons are edited in the course itself, and change here too.": "Moduły i lekcje tego kursu edytuje się w samym kursie; zmiany widać też tutaj.",
 "This device": "To urządzenie",
 "This email appears on customer receipts and order confirmations. Customers write to it for support.": "Ten e-mail widnieje na paragonach i potwierdzeniach zamówień. Klienci piszą na niego po pomoc.",
