 "This email was changed somewhere else.": "Ten e-mail został zmieniony gdzie indziej.",
 "This email was not sent. {lastError} Fix it and send it again.": "Ten e-mail nie został wysłany. {lastError} Popraw go i wyślij ponownie.",
 "This email, as your subscribers get it, to your own address.": "Ten e-mail, tak jak dostają go subskrybenci, na Twój własny adres.",
 "This event is cancelled and nobody has had their money back yet. Refund each ticket below, or ask the owner to.": "To wydarzenie jest odwołane i nikt jeszcze nie odzyskał pieniędzy. Zwróć każdy bilet poniżej lub poproś o to właściciela.",
