 "This program is sold on its own. Buy it once and it stays in your Learn for as long as you are a member.": "Ten program jest sprzedawany osobno. Kup go raz, a zostanie w Twojej Nauce, dopóki jesteś członkiem.",
 "This program opens at {value}. Levels come from taking part in the community.": "Ten program otwiera się na: {value}. Poziomy zdobywa się, biorąc udział w społeczności.",
 "This sale cannot be refunded.": "Tej sprzedaży nie można zwrócić.",
 "This text": "Ten tekst",
 "This text appears on your customer's bank statement to identify who charged them.": "Ten tekst pojawia się na wyciągu klienta, aby wiedział, kto go obciążył.",
 "This text appears on your customers' bank statements. It helps them identify the charge. Format: \"(Your Name) - STORELIB\". Only your name can be changed. Max 22 characters total.": "Ten tekst pojawia się na wyciągach klientów i pomaga im rozpoznać obciążenie. Format: „(Twoja nazwa) - STORELIB”. Zmienić można tylko nazwę. Łącznie maks. 22 znaki.",
